"use client";

/**
 * Launch hero: two product cards slide in from opposite sides and settle into
 * an overlapping pair, while the launch headline and its subline settle above.
 *
 * Written by Better Design. Without pictures each card draws a skeleton of a
 * product screen from the theme, one dashboard and one list.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, springs, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin"] });

const CARD_W = 820;
const CARD_H = 512;
const BAR = 44;

/** A shadow ink that stays dark in both modes, so a dark theme never glows. */
const shade = (alpha: number): string => `oklch(0.14 0.01 60 / ${alpha})`;


export interface LaunchHeroProps {
  headline?: string;
  /** One supporting line under the headline. */
  subline?: string;
  /** Up to two image paths, left card first. Unset, each card draws a skeleton screen. */
  pictures?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const line = (theme: VideoTheme, width: number | string, alpha = 0.1, height = 12) => (
  <div style={{ width, height, borderRadius: height / 2, background: withAlpha(theme.foreground, alpha) }} />
);

function Dashboard({ theme }: { theme: VideoTheme }) {
  const bars = [0.42, 0.58, 0.5, 0.74, 0.62, 0.86, 0.7, 0.94];
  return (
    <div style={{ display: "flex", height: "100%" }}>
      <div style={{ width: 170, background: theme.muted, padding: 24, display: "flex", flexDirection: "column", gap: 18 }}>
        {[0.8, 0.6, 0.7, 0.5, 0.65].map((w, i) => (
          <div key={i}>{line(theme, `${w * 100}%`, i === 1 ? 0.28 : 0.1)}</div>
        ))}
      </div>
      <div style={{ flex: 1, padding: 28, display: "flex", flexDirection: "column", gap: 22 }}>
        {line(theme, 220, 0.18, 16)}
        <div style={{ display: "flex", gap: 16 }}>
          {[0, 1, 2].map((i) => (
            <div key={i} style={{ flex: 1, height: 84, borderRadius: theme.radius, border: `1px solid ${theme.border}`, padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
              {line(theme, "50%", 0.1, 10)}
              {i === 0 ? <div style={{ width: "70%", height: 18, borderRadius: 9, background: theme.primary }} /> : line(theme, "70%", 0.2, 18)}
            </div>
          ))}
        </div>
        <div style={{ flex: 1, display: "flex", alignItems: "flex-end", gap: 14, padding: "0 4px" }}>
          {bars.map((h, i) => (
            <div key={i} style={{ flex: 1, height: `${h * 100}%`, borderRadius: 6, background: i === bars.length - 1 ? theme.primary : withAlpha(theme.primary, 0.26) }} />
          ))}
        </div>
      </div>
    </div>
  );
}

function List({ theme }: { theme: VideoTheme }) {
  return (
    <div style={{ padding: 30, display: "flex", flexDirection: "column", gap: 14 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
        {line(theme, 200, 0.18, 16)}
        <div style={{ width: 112, height: 36, borderRadius: 18, background: theme.primary }} />
      </div>
      {[0, 1, 2, 3].map((i) => (
        <div
          key={i}
          style={{
            display: "flex",
            alignItems: "center",
            gap: 18,
            padding: "14px 16px",
            borderRadius: theme.radius,
            background: i === 1 ? withAlpha(theme.primary, 0.1) : "transparent",
            border: `1px solid ${i === 1 ? withAlpha(theme.primary, 0.3) : theme.border}`,
          }}
        >
          <div style={{ width: 36, height: 36, borderRadius: 18, background: withAlpha(theme.primary, 0.7 - i * 0.12) }} />
          <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 9 }}>
            {line(theme, `${60 - i * 6}%`, 0.16, 11)}
            {line(theme, `${38 + i * 5}%`, 0.08, 9)}
          </div>
          {line(theme, 60, 0.1, 11)}
        </div>
      ))}
    </div>
  );
}

function ProductCard({ theme, picture, kind }: { theme: VideoTheme; picture?: string; kind: 0 | 1 }) {
  return (
    <div
      style={{
        width: CARD_W,
        height: CARD_H,
        borderRadius: theme.radius + 10,
        overflow: "hidden",
        background: theme.card,
        border: `1px solid ${theme.border}`,
        boxShadow: `0 50px 90px -40px ${shade(0.45)}, 0 12px 24px -16px ${shade(0.22)}`,
      }}
    >
      <div style={{ height: BAR, display: "flex", alignItems: "center", gap: 8, padding: "0 18px", borderBottom: `1px solid ${theme.border}` }}>
        {[0, 1, 2].map((i) => (
          <div key={i} style={{ width: 12, height: 12, borderRadius: 6, background: withAlpha(theme.foreground, 0.14) }} />
        ))}
        <div style={{ marginLeft: 18, width: 240, height: 20, borderRadius: 10, background: theme.muted }} />
      </div>
      <div style={{ height: CARD_H - BAR }}>
        {picture ? <Img src={srcOf(picture)} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : kind === 0 ? <Dashboard theme={theme} /> : <List theme={theme} />}
      </div>
    </div>
  );
}

/** Two product cards slide into an overlapping pair under a settling launch headline. */
export function LaunchHero({
  headline = "Introducing Your product",
  subline = "Everything your team needs to ship, in one place.",
  pictures = [],
  theme: themeOverride,
  font,
}: LaunchHeroProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);

  const head = easings.out(progress(frame, 2, 24));
  const sub = easings.out(progress(frame, 12, 24));
  const left = spring({ frame: frame - 14, fps, config: springs.soft });
  const right = spring({ frame: frame - 22, fps, config: springs.soft });

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      <AbsoluteFill style={{ background: `radial-gradient(ellipse 1300px 620px at 50% 78%, ${withAlpha(theme.primary, 0.12)}, ${withAlpha(theme.primary, 0)} 70%)` }} />
      <div style={{ position: "absolute", top: 108, left: 0, right: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 22, textAlign: "center" }}>
        <div style={{ fontSize: 88, fontWeight: 700, letterSpacing: "-0.045em", lineHeight: 1.02, color: theme.foreground, opacity: head, transform: `translateY(${(1 - head) * 28}px)` }}>
          {headline}
        </div>
        <div style={{ fontSize: 36, fontWeight: 500, letterSpacing: "-0.015em", color: theme.mutedForeground, opacity: sub, transform: `translateY(${(1 - sub) * 20}px)` }}>
          {subline}
        </div>
      </div>
      <div style={{ position: "absolute", left: "50%", top: 676 }}>
        <div style={{ position: "absolute", left: -CARD_W / 2, top: -CARD_H / 2, transform: `translate(${-250 - (1 - left) * 1500}px, ${-6}px) rotate(${-3 - (1 - left) * 6}deg)` }}>
          <ProductCard theme={theme} picture={pictures[0]} kind={0} />
        </div>
        <div style={{ position: "absolute", left: -CARD_W / 2, top: -CARD_H / 2, transform: `translate(${250 + (1 - right) * 1500}px, ${64}px) rotate(${2.5 + (1 - right) * 6}deg)` }}>
          <ProductCard theme={theme} picture={pictures[1]} kind={1} />
        </div>
      </div>
    </AbsoluteFill>
  );
}
